import{_ as o,o as a,c as t,ag as r}from"./chunks/framework.8tqBsFWt.js";const h=JSON.parse(`{"title":"Time off","description":"How to request PTO, log sick days, and see your team's approved absences in VERA.","frontmatter":{"description":"How to request PTO, log sick days, and see your team's approved absences in VERA."},"headers":[],"relativePath":"guide/time-off.md","filePath":"guide/time-off.md"}`),s={name:"guide/time-off.md"};function n(i,e,l,d,u,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="time-off" tabindex="-1">Time off <a class="header-anchor" href="#time-off" aria-label="Permalink to &quot;Time off&quot;">​</a></h1><p>Time off — holidays, sick days, and leave — goes through VERA&#39;s approval process rather than being logged as ordinary time. This keeps your manager in the loop and ensures your capacity is reflected accurately.</p><hr><h2 id="requesting-time-off-pto-holiday" tabindex="-1">Requesting time off (PTO / holiday) <a class="header-anchor" href="#requesting-time-off-pto-holiday" aria-label="Permalink to &quot;Requesting time off (PTO / holiday)&quot;">​</a></h2><ol><li>Open <strong>Time Off</strong> in the side menu (or go to <a href="https://app.getvera.site/console/my-time-off" target="_blank" rel="noreferrer">app.getvera.site/console/my-time-off</a>).</li><li>Click <strong>Request time off</strong> and choose your date(s).</li><li>Submit. Your request goes to your manager for approval.</li></ol><p>The date picker won&#39;t let you book inside your organisation&#39;s notice window, so you&#39;ll always be requesting far enough ahead. Once submitted, your manager is notified and can approve or decline.</p><p><strong>Important:</strong> Don&#39;t try to log time against a holiday or &quot;out of office&quot; project directly — time off must go through this request process so your manager is aware and your capacity stays accurate.</p><hr><h2 id="viewing-your-requests" tabindex="-1">Viewing your requests <a class="header-anchor" href="#viewing-your-requests" aria-label="Permalink to &quot;Viewing your requests&quot;">​</a></h2><p>The <strong>Time Off</strong> page shows all your requests in one list with their current status — pending, approved, or declined. While a request is still pending you can <strong>edit</strong> its dates or <strong>cancel</strong> it; once it&#39;s been actioned by your manager it&#39;s locked.</p><hr><h2 id="sick-days-and-leave" tabindex="-1">Sick days and leave <a class="header-anchor" href="#sick-days-and-leave" aria-label="Permalink to &quot;Sick days and leave&quot;">​</a></h2><p>If you&#39;re unwell, let your manager know — they&#39;ll record the sick day for you from the console. You don&#39;t need to file a formal request for a sick day.</p><p>Extended leave (parental, compassionate, unpaid, and so on) follows the same request-and-approve flow as holiday: submit it from the <strong>Time Off</strong> page and your manager approves.</p><hr><h2 id="for-managers-approving-requests" tabindex="-1">For managers: approving requests <a class="header-anchor" href="#for-managers-approving-requests" aria-label="Permalink to &quot;For managers: approving requests&quot;">​</a></h2><p>Open <strong>Approvals</strong> in the console to see every pending request from your team. For each one you can <strong>approve</strong> or <strong>decline</strong>. VERA notifies the team member of the outcome and, on approval, records the time off against their schedule so capacity reflects it.</p><p>The <strong>Time Off</strong> management view (owners) shows the whole team&#39;s booked and pending time off, and lets you log a sick day or leave on someone&#39;s behalf.</p><hr><h2 id="company-holidays" tabindex="-1">Company holidays <a class="header-anchor" href="#company-holidays" aria-label="Permalink to &quot;Company holidays&quot;">​</a></h2><p>Your organisation&#39;s public holidays are set up by an owner and are automatically factored into capacity calculations — you don&#39;t request them individually. Anyone can see the list on the <strong>Calendar</strong> page in the console.</p>',21)])])}const f=o(s,[["render",n]]);export{h as __pageData,f as default};
